  eq('엔진: 내 학교 글', eng.activityForProfile({ school: '한국외국어대학교', campus: '', url: 'u' }, P), true);
  eq('엔진: 다른 학교 글은 아님', eng.activityForProfile({ school: '경희대학교', campus: '', url: 'u' }, P), false);
