  eq('  같은 시·도인데 시·군을 안 골랐으면 미달이 아니라 미확인 (전남 학생 · 광양시)',
    verdict(mk('백운장학회(광양)', '광양시에 주소를 두고 재학 중인 학생'), { region: '전남', parentRegion: '전남' }), '미확인');
  /* 🔴 예외 문구가 있으면 ✕ 를 치지 않는다 — `대학생은 관외 거주 인정` 이 실제로 있다 */
