  eq('  그때 옛 값이 그대로 남는다', blank.after[0].documents, ['재학증명서']);
  eq('  이름도 마찬가지', run('edit', { edits: [{ id: 'reg-t0', patch: { name: '' } }] }).status !== 0, true);
  /* 막기만 하고 고치는 길을 안 내주면 사람이 갇힌다 */
