    const h16 = (s) => createHash('sha256').update(s).digest('hex').slice(0, 16);
    eq('⓪ 4번 지시문(SYSTEM)과 카드 규칙(CARD_RULES)이 바이트까지 그대로다', [h16(CR.SYSTEM), h16(CR.CARD_RULES)], ['8f0be3fb63149028', 'ecc5622301936bfa']);
