        const drops = [V('form', 'a', 'broken', '2쪽의 표가 무너졌다'), V('doc', 'c', 'wrong', '2025학년도 공고문이다'), V('pages', 'e', 'empty', '빈 쪽뿐이다'), V('form', 'g', 'empty', '그림 하나뿐이다', { id: 'n2' })];
        const texts = () => Object.values(IDX).map((rel) => vb.read(rel));
